-- Temporario e somente leitura. Remover a funcao ao terminar a exportacao.
create or replace function public.exportar_estrutura_recuperacao()
returns jsonb language sql security definer set search_path=pg_catalog as $export$
select jsonb_build_object(
 'types',(select coalesce(jsonb_agg(format('create type public.%I as enum (%s);',t.typname,(select string_agg(quote_literal(e.enumlabel),',' order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid)) order by t.typname),'[]') from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typtype='e'),
 'tables',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'ddl',format('create table public.%I (%s);',c.relname,(select string_agg(format('%I %s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),case when a.attgenerated='s' then ' generated always as ('||pg_get_expr(d.adbin,d.adrelid)||') stored' when a.attidentity<>'' then ' generated '||case when a.attidentity='a' then 'always' else 'by default' end||' as identity' when d.oid is not null then ' default '||pg_get_expr(d.adbin,d.adrelid) else '' end,case when a.attnotnull then ' not null' else '' end),', ' order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)),'rls',c.relrowsecurity,'force',c.relforcerowsecurity) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('type',con.contype,'ddl',format('alter table public.%I add constraint %I %s;',c.relname,con.conname,pg_get_constraintdef(con.oid,true))) order by case when con.contype='f' then 1 else 0 end,c.relname,con.conname),'[]') from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),
 'indexes',(select coalesce(jsonb_agg(pg_get_indexdef(i.indexrelid)||';' order by c.relname,ic.relname),'[]') from pg_index i join pg_class c on c.oid=i.indrelid join pg_class ic on ic.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not exists(select 1 from pg_constraint con where con.conindid=i.indexrelid)),
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'ddl',pg_get_functiondef(p.oid),'signature',p.oid::regprocedure::text,'acl',(select coalesce(jsonb_agg(jsonb_build_object('grantee',case when x.grantee=0 then 'public' else r.rolname end,'privilege',x.privilege_type)),'[]') from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x left join pg_roles r on r.oid=x.grantee where x.grantee=0 or r.rolname in ('anon','authenticated','service_role'))) order by p.proname,p.oid),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and p.proname<>'exportar_estrutura_recuperacao' and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
 'views',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'ddl',format('create view public.%I%s as %s',c.relname,case when c.reloptions is not null then ' with ('||array_to_string(c.reloptions,',')||')' else '' end,pg_get_viewdef(c.oid,true)),'dependencies',(select coalesce(jsonb_agg(distinct other.relname),'[]') from pg_rewrite rw join pg_depend d on d.objid=rw.oid join pg_class other on other.oid=d.refobjid where rw.ev_class=c.oid and other.relkind='v' and other.oid<>c.oid)) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='v'),
 'triggers',(select coalesce(jsonb_agg(pg_get_triggerdef(t.oid,true)||';' order by c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace pn on pn.oid=p.pronamespace where not t.tgisinternal and (n.nspname='public' or (n.nspname='auth' and c.relname='users' and pn.nspname='public'))),
 'policies',(select coalesce(jsonb_agg(format('create policy %I on %I.%I as %s for %s to %s%s%s;',p.polname,n.nspname,c.relname,case when p.polpermissive then 'permissive' else 'restrictive' end,case p.polcmd when '*' then 'all' when 'r' then 'select' when 'a' then 'insert' when 'w' then 'update' when 'd' then 'delete' end,(select string_agg(case when roleid=0 then 'public' else quote_ident(r.rolname) end,',') from unnest(p.polroles) roleid left join pg_roles r on r.oid=roleid),case when p.polqual is not null then ' using ('||pg_get_expr(p.polqual,p.polrelid)||')' else '' end,case when p.polwithcheck is not null then ' with check ('||pg_get_expr(p.polwithcheck,p.polrelid)||')' else '' end) order by c.relname,p.polname),'[]') from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' or (n.nspname='storage' and c.relname='objects' and (coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'')) like '%fotos_alunos%')),
 'grants',(select coalesce(jsonb_agg(format('grant %s on table public.%I to %s;',x.privilege_type,c.relname,case when x.grantee=0 then 'public' else quote_ident(r.rolname) end) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x left join pg_roles r on r.oid=x.grantee where n.nspname='public' and c.relkind in ('r','v') and (x.grantee=0 or r.rolname in ('anon','authenticated','service_role'))),
 'buckets',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)),'[]') from storage.buckets where id='fotos_alunos'),
 'saved_report_constraints',(select coalesce(jsonb_agg(pg_get_constraintdef(oid)),'[]') from pg_constraint where conrelid='public.relatorios_salvos'::regclass)
);
$export$;
revoke all on function public.exportar_estrutura_recuperacao() from public,anon,authenticated;
grant execute on function public.exportar_estrutura_recuperacao() to service_role;
notify pgrst,'reload schema';
